// Flatten each Gmail message into one stable shape so that no downstream node has to
// guess at Gmail's field names. Attachments are re-attached to the item unchanged.
const MAX_BODY = 12000;

function toText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (Array.isArray(value.value)) {
      return value.value.map((v) => v.address || v.name || '').filter(Boolean).join(', ');
    }
  }
  return String(value);
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// The .NET webhook compares received_at against UtcNow, so always hand it ISO-8601 UTC.
function toIsoUtc(value) {
  if (value === undefined || value === null || value === '') return null;
  const asNumber = Number(value);
  const looksEpoch = Number.isFinite(asNumber) && String(value).trim().length >= 10;
  const date = new Date(looksEpoch ? asNumber : String(value));
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

const out = [];

for (const item of $input.all()) {
  const json = item.json || {};
  const headers = json.headers || {};
  const binary = item.binary || {};
  const attachmentKeys = Object.keys(binary).filter((k) => k.startsWith('attachment_'));

  const from = toText(json.from) || toText(headers.from) || toText(headers.From);
  const fromEmail = from.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);

  const body =
    toText(json.text) ||
    toText(json.textPlain) ||
    stripHtml(json.html || json.textHtml);

  out.push({
    json: {
      message_id: String(json.id || json.messageId || ''),
      thread_id: String(json.threadId || ''),
      subject: toText(json.subject) || toText(headers.subject) || toText(headers.Subject),
      from,
      from_email: fromEmail ? fromEmail[0].toLowerCase() : '',
      body,
      body_excerpt: body.slice(0, MAX_BODY),
      received_at:
        toIsoUtc(json.date) ||
        toIsoUtc(headers.date || headers.Date) ||
        toIsoUtc(json.internalDate) ||
        new Date().toISOString(),
      attachment_count: attachmentKeys.length,
      attachment_keys: attachmentKeys
    },
    binary
  });
}

return out;

// Re-attach the normalized email fields (the PDF node overwrites json) and add the
// resume text. Index alignment is safe: both upstream nodes are strictly 1:1.
const MAX_RESUME = 8000;

const emails = $('Normalize Email').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const context = { ...((emails[i] && emails[i].json) || {}) };
  const extracted = (items[i] && items[i].json) || {};
  const resumeText = typeof extracted.text === 'string' ? extracted.text : '';

  context.resume_text = resumeText.replace(/\s{3,}/g, ' ').trim().slice(0, MAX_RESUME);
  out.push({ json: context });
}

return out;

